use renderer::engine::{Draw, Engine, IDENTITY, Material, MeshData, Vertex, View};
use renderer::graph::{BufferDesc, Graph};
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

struct Counter;
static COUNTING: AtomicBool = AtomicBool::new(false);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
static BYTES: AtomicUsize = AtomicUsize::new(0);
#[global_allocator]
static ALLOCATOR: Counter = Counter;
unsafe impl GlobalAlloc for Counter {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        if COUNTING.load(Ordering::Relaxed) {
            ALLOCS.fetch_add(1, Ordering::Relaxed);
            BYTES.fetch_add(layout.size(), Ordering::Relaxed);
        }
        unsafe { System.alloc(layout) }
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
        unsafe { System.dealloc(pointer, layout) }
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        if COUNTING.load(Ordering::Relaxed) {
            ALLOCS.fetch_add(1, Ordering::Relaxed);
            BYTES.fetch_add(size, Ordering::Relaxed);
        }
        unsafe { System.realloc(pointer, layout, size) }
    }
}
fn measure<T>(f: impl FnOnce() -> T) -> (T, usize, usize) {
    ALLOCS.store(0, Ordering::Relaxed);
    BYTES.store(0, Ordering::Relaxed);
    COUNTING.store(true, Ordering::Relaxed);
    let result = std::hint::black_box(f());
    COUNTING.store(false, Ordering::Relaxed);
    (result, ALLOCS.load(Ordering::Relaxed), BYTES.load(Ordering::Relaxed))
}
fn main() {
    let mut graph = Graph::new();
    for index in 0..2048 {
        let buffer = graph.buffer(format!("resource {index}"), BufferDesc { size: 4 }).unwrap();
        graph.upload_buffer(format!("upload {index}"), buffer, 0, vec![0; 4]).unwrap();
        graph.readback_buffer(format!("readback {index}"), buffer, 0, 4).unwrap();
    }
    let (plan, calls, bytes) = measure(|| graph.compile().unwrap());
    assert_eq!(plan.pass_count(),4096);
    println!("compile resources=2048 passes=4096 allocations={calls} allocated_bytes={bytes}");
    let mut engine = Engine::new(1,1).unwrap();
    let mesh = engine.create_mesh(MeshData::new(&[
        Vertex { position:[-1.0,-1.0,0.5], color:[1.0;4] },
        Vertex { position:[1.0,-1.0,0.5], color:[1.0;4] },
        Vertex { position:[0.0,1.0,0.5], color:[1.0;4] },
    ], &[0,1,2]).unwrap()).unwrap();
    let material=engine.create_material(Material::default()).unwrap();
    let view=View{ width:32,height:32,clip_from_world:IDENTITY,clear_color:[0.0;4] };
    let draws=vec![Draw{mesh,material,world_from_model:IDENTITY};8192];
    let snapshot=engine.snapshot(&view,&draws).unwrap();
    let (frame,calls,bytes)=measure(||snapshot.build_graph(false,|_,color| Ok(color)).unwrap());
    assert_eq!(frame.graph.compile().unwrap().pass_count(),3);
    println!("frame_build draws=8192 allocations={calls} allocated_bytes={bytes}");
}
